test('lateFee scales with invoice amount', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(draft1.ok, true);

  const inv1 = issueInvoice(draft1.value, []);
  assert.equal(inv1.ok, true);

  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(draft2.ok, true);

  const inv2 = issueInvoice(draft2.value, []);
  assert.equal(inv2.ok, true);

  const fee1 = lateFee(inv1.value, '2025-02-05');
  const fee2 = lateFee(inv2.value, '2025-02-05');

  // Fee should be roughly 2x for 2x the amount
  assert(fee2 > fee1);
  assert(fee2 > fee1 * 1.5);
});

test('lateFee accumulates with days', () => {
  const inv = createTestInvoice('C-001', '2025-01-15', 'NET14');
  assert.equal(inv.ok, true);

  const { total } = invoiceTotals(inv.value);
  const fee1Day = lateFee(inv.value, '2025-01-30');
  const fee2Day = lateFee(inv.value, '2025-01-31');

  // 2 days should have more fee than 1 day
  assert(fee2Day > fee1Day);

  // Difference should be about 1 day's fee
  const oneDay = roundCents(total * 0.0004);
  assert.equal(fee2Day - fee1Day, oneDay);
});

