  const fee1Day = lateFee(inv.value, '2025-01-30');
  const fee2Day = lateFee(inv.value, '2025-01-31');

  // 2 days should have more fee than 1 day
  assert(fee2Day > fee1Day);

  // Difference should be about 1 day's fee
  const oneDay = roundCents(total * 0.0004);
  assert.equal(fee2Day - fee1Day, oneDay);
});

