7	/**
8	 * Find invoices that are overdue.
9	 * @param {Array<{ customerId: string, number?: string, issueDate: string, dueDate?: string, status: string, lines: Array, payments?: Array, voucher?: { code: string, amount: number } }>} invoices
10	 * @param {string} asOf Date in YYYY-MM-DD format
11	 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
12	 */
13	export function overdueInvoices(invoices, asOf) {
14	  const overdue = invoices
15	    .filter((inv) => {
16	      // Must be issued or partially_paid
17	      if (inv.status !== 'issued' && inv.status !== 'partially_paid') {
18	        return false;
19	      }
20	
21	      // Must have a due date
22	      if (!inv.dueDate) {
23	        return false;
24	      }
25	
26	      // Due date must be before asOf
27	      if (inv.dueDate >= asOf) {
28	        return false;
29	      }
30	
31	      return true;
32	    })
33	    .map((inv) => {
34	      const daysOverdue = daysBetween(inv.dueDate, asOf);
35	      const due = balanceDue(inv);
36	
37	      return {
38	        number: inv.number,
39	        customerId: inv.customerId,
40	        dueDate: inv.dueDate,
41	        daysOverdue,
42	        due,
43	      };
44	    })
45	    .sort((a, b) => b.daysOverdue - a.daysOverdue);
46	
47	  return overdue;
48	}
