50	/**
51	 * Generate a VAT summary across invoices.
52	 * @param {Array<{ customerId: string, number?: string, issueDate: string, dueDate?: string, status: string, lines: Array, payments?: Array, voucher?: { code: string, amount: number } }>} invoices
53	 * @returns {Array<{ rate: number, base: number, vat: number }>} Grouped by VAT rate, sorted by rate descending
54	 */
55	export function vatSummary(invoices) {
56	  const vatMap = new Map();
57	
58	  for (const invoice of invoices) {
59	    // Filter by status
60	    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
61	      continue;
62	    }
63	
64	    // Process each line
65	    for (const line of invoice.lines) {
66	      // Get product to get unitPrice
67	      const productResult = getProduct(line.sku);
68	      if (!productResult.ok) continue;
69	
70	      const product = productResult.value;
71	      const enrichedLine = {
72	        qty: line.qty,
73	        unitPrice: product.unitPrice,
74	        discountPercent: line.discountPercent,
75	        vatRate: line.vatRate,
76	      };
77	
78	      // Calculate line amounts
79	      const total = lineTotal(enrichedLine);
80	      const discount = lineDiscount(enrichedLine);
81	      const base = Math.max(0, total - discount);
82	      const vat = lineVAT(enrichedLine);
83	
84	      // Accumulate by VAT rate
85	      const vatRate = line.vatRate;
86	      if (!vatMap.has(vatRate)) {
87	        vatMap.set(vatRate, { base: 0, vat: 0 });
88	      }
89	      const entry = vatMap.get(vatRate);
90	      entry.base += base;
91	      entry.vat += vat;
92	    }
93	  }
94	
95	  // Convert to array and sort by rate descending
96	  return Array.from(vatMap.entries())
97	    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
98	    .sort((a, b) => b.rate - a.rate);
99	}
