101	/**
102	 * Calculate late fee on an invoice: 0.04% of balance due per day overdue.
103	 * @param {{ customerId: string, number?: string, issueDate: string, dueDate?: string, status: string, lines: Array, payments?: Array, voucher?: { code: string, amount: number } }} invoice
104	 * @param {string} asOf Date in YYYY-MM-DD format
105	 * @returns {number} Late fee in cents, or 0 if not overdue
106	 */
107	export function lateFee(invoice, asOf) {
108	  // Draft invoices don't have late fees
109	  if (invoice.status === 'draft') {
110	    return 0;
111	  }
112	
113	  // Check if invoice has a due date
114	  if (!invoice.dueDate) {
115	    return 0;
116	  }
117	
118	  // Check if invoice is overdue
119	  if (invoice.dueDate >= asOf) {
120	    return 0;
121	  }
122	
123	  // Calculate days overdue
124	  const daysOverdue = daysBetween(invoice.dueDate, asOf);
125	
126	  // Calculate balance due
127	  const due = balanceDue(invoice);
128	
129	  // If no balance due, no late fee
130	  if (due <= 0) {
131	    return 0;
132	  }
133	
134	  // Calculate late fee: 0.04% per day = 0.0004 per day
135	  const fee = roundCents(due * daysOverdue * 0.0004);
136	
137	  return Math.max(0, fee);
138	}
