  assert.equal(result.topCustomers[0].due, total1 + total2);
});

test('dashboard normalizes customer IDs', () => {
  const draft = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  });

  const inv = issueInvoice(draft.value, []);
