  assert.equal(result.counts.partially_paid, 1);
  assert.equal(result.counts.paid, 1);
});

test('dashboard overdue excludes future invoices', () => {
  const inv = createTestInvoice('C-001', '2025-01-15', 'NET30');

  const result = dashboard([inv.value], '2025-02-10');

  assert.equal(result.overdue.count, 0);
  assert.equal(result.overdue.amount, 0);
});

test('dashboard outstanding is separate from overdue', () => {
  const inv1 = createTestInvoice('C-001', '2025-01-15', 'NET30'); // Not overdue on 2025-02-10
  const inv2 = createTestInvoice('C-002', '2025-01-15', 'NET14'); // Overdue on 2025-02-10

  const result = dashboard([inv1.value, inv2.value], '2025-02-10');

  assert(result.outstanding > 0);
  assert(result.overdue.amount > 0);
  assert(result.outstanding > result.overdue.amount);
});

test('dashboard with zero due amounts', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  const { total } = invoiceTotals(inv.value);
  const paid = recordPayment(inv.value, { amount: total, date: '2025-01-20' });

  const result = dashboard([paid.value], '2025-02-15');

  assert.equal(result.outstanding, 0);
  assert.equal(result.topCustomers.length, 0);
});

test('dashboard returns structure with all required fields', () => {
  const result = dashboard([], '2025-02-15');

  assert(result.hasOwnProperty('counts'));
  assert(result.hasOwnProperty('outstanding'));
  assert(result.hasOwnProperty('overdue'));
  assert(result.hasOwnProperty('topCustomers'));

  assert(result.counts.hasOwnProperty('draft'));
  assert(result.counts.hasOwnProperty('issued'));
  assert(result.counts.hasOwnProperty('partially_paid'));
  assert(result.counts.hasOwnProperty('paid'));

  assert(result.overdue.hasOwnProperty('count'));
  assert(result.overdue.hasOwnProperty('amount'));

  assert(Array.isArray(result.topCustomers));
});

